const root=document.querySelector('.device');const screens=[...root.children];let active=0;const historyStack=[];let speakingCorrect=false;let speechAttempts=0;let speechHints=0;let recalled=false;let selected=null;
function find(i,name){const matches=[...screens[i].querySelectorAll('[data-pencil-name]')].filter(el=>el.dataset.pencilName.replace(/\s+/g,'')===name.replace(/\s+/g,''));return matches.find(el=>el.style.display==='flex')||matches[0]}
function action(i,name,fn,icon=false){const el=find(i,name);if(!el)return;el.classList.add('action');if(icon)el.classList.add('icon-action');el.tabIndex=0;el.setAttribute('role','button');el.setAttribute('aria-label',name);el.onclick=fn;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn()}}}
function show(i,remember=true){if(i!==active&&remember)historyStack.push(active);active=i;screens.forEach((s,j)=>s.classList.toggle('active',i===j));document.querySelectorAll('.studio nav button').forEach((b,j)=>b.classList.toggle('current',i===j));window.scrollTo(0,0)}
function note(i,text){const foot=find(i,'Bottom actions');let el=foot.querySelector('.inline-note');if(!el){el=document.createElement('p');el.className='inline-note';el.setAttribute('role','status');foot.prepend(el)}el.textContent=text}
function sheet(title,text,done='知道了',onDone=null){const overlay=document.createElement('div');overlay.className='sheet-wrap';const section=document.createElement('section');section.className='sheet';section.setAttribute('role','dialog');section.setAttribute('aria-modal','true');section.setAttribute('aria-label',title);section.innerHTML='<div class="handle"></div>';const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=text;const b=document.createElement('button');b.textContent=done;const focusBefore=document.activeElement;const close=()=>{overlay.remove();if(onDone)onDone();else focusBefore?.focus()};b.onclick=close;section.append(h,p,b);overlay.append(section);root.append(overlay);b.focus();overlay.onkeydown=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){e.preventDefault();b.focus()}}}
function entry(i,name,label,placeholder){const area=find(i,name);area.replaceChildren();const input=document.createElement('textarea');input.setAttribute('aria-label',label);input.placeholder=placeholder;area.append(input);return input}
function clean(v){return v.toLowerCase().replace(/[’]/g,"'").replace(/[.,!?]/g,'').replace(/\s+/g,' ').trim()}
function speak(text,rate=.88){if(!('speechSynthesis' in window)){sheet('此浏览器不支持朗读','请在支持语音合成的浏览器中体验。');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=rate;speechSynthesis.speak(u)}
const names=['今日','温习旧句','先听懂','句中学词','自己说','表达反馈','读与写','无提示检验','今日完成','成长','句库','Plus'];const nav=document.querySelector('.studio nav');names.forEach((name,i)=>{const b=document.createElement('button');b.textContent=name;b.onclick=()=>show(i);nav.append(b)});
screens.forEach((s,i)=>{if(find(i,'Navigation bar')){action(i,'chevron.left',()=>show(historyStack.pop()??0,false),true);action(i,'ellipsis',()=>sheet('今日学习安排','复习 4 分钟、听读与句中学词 8 分钟、说写表达 8 分钟、无提示检验 4 分钟。此预览演示流程，不计真实学习时长。'),true)}if(find(i,'Tab bar')){action(i,'今日',()=>show(0));action(i,'句库',()=>show(10));action(i,'成长',()=>show(9))}});
action(0,'开始今天的练习',()=>show(1));action(0,'person.crop.circle',()=>show(11),true);
const recall=entry(1,'Recall input','把我通常九点开始工作译成英语','先自己试一句…');action(1,'Recall hint',()=>{sheet('给你一点提示','用 I usually… 表达「我通常……」，然后说明几点开始工作。')});action(1,'检查这句话',()=>{if(recalled){show(2);return}if(!recall.value.trim()){recall.focus();note(1,'先写一句，再来检查。');return}const ok=['i usually start work at nine','i usually start work at 9','i usually begin work at nine'].includes(clean(recall.value));if(ok){recalled=true;note(1,'这句独立说对了。接下来认识新同事。');find(1,'检查这句话').textContent='继续今天的新情境';find(1,'检查这句话').setAttribute('aria-label','继续今天的新情境')}else sheet('参考表达','I usually start work at nine. 本原型仅演示固定表达的核对；其他有效说法需要正式版的评估服务。','再试一次',()=>recall.focus())});
action(2,'Play audio',()=>speak("Hi, I'm Alex. I just joined the team.",.8));action(2,'gobackward',()=>speak("Hi, I'm Alex. I just joined the team.",.8),true);action(2,'0.8×',()=>speak("Hi, I'm Alex. I just joined the team.",.65));for(const name of ['刚刚加入','已经一年','还没有加入'])action(2,name,()=>{selected=name;for(const n of ['刚刚加入','已经一年','还没有加入'])find(2,n).style.backgroundColor=n===name?'#e1e9ff':'#ffffff';note(2,'已选择：'+name)});action(2,'确认，再看完整句子',()=>{if(!selected){note(2,'先选择你听到的信息。');return}if(selected!=='刚刚加入'){note(2,'再听一次，注意 just joined。');return}show(3)});
action(3,'Sentence audio',()=>speak('I just joined the team.'));action(3,'收起示范，换我来说',()=>show(4));
const spoken=entry(4,'Transcription','告诉新同事你刚加入设计团队','你的英文表达…');spoken.style.height='58px';action(4,'Hold to speak',()=>sheet('口语练习的体验方式','原型尚未接入录音与语音识别。请用文字体验：正式版先转写，允许修正识别错误，再给语言反馈。','用文字试一句',()=>spoken.focus()));action(4,'改用文字输入',()=>spoken.focus());action(4,'Hint disclosure',()=>{speechHints++;sheet('一点提示',speechHints===1?'这件事已经发生了，想想 join 要怎样变化。':speechHints===2?'试试用 I just joined… 开头。':'I just joined the design team. 下一次会收起这句，再让你独立表达。')});
action(4,'提交，看看怎样更自然',()=>{if(!spoken.value.trim()){spoken.focus();note(4,'先说出或写下你的表达。');return}speechAttempts++;speakingCorrect=['i just joined the design team','i have just joined the design team'].includes(clean(spoken.value));find(5,'I just join design team.').textContent=spoken.value;find(5,'意思说到了，\n再调整一个地方。').textContent=speakingCorrect?(speechAttempts>1?'这次，你用出来了。':'这句，你独立用出来了。'):'看看这句可以怎样表达。';find(5,'先说出想法，是很好的开始。').textContent=speakingCorrect?(speechAttempts>1?'练习后的成功会单独记录。':speechHints?'借助提示完成，之后再独立检验。':'没有看示范，完成了自我介绍。'):'原型使用固定表达示例，不能判断所有有效说法。';find(5,'收起示范，再说一次').textContent=speakingCorrect?'接着读一条工作消息':'收起示范，再说一次';find(5,'收起示范，再说一次').setAttribute('aria-label',speakingCorrect?'接着读一条工作消息':'收起示范，再说一次');show(5)});
action(5,'Feedback playback',()=>speak('I just joined the design team.'));action(5,'收起示范，再说一次',()=>{if(speakingCorrect)show(6);else {spoken.value='';show(4);spoken.focus()}});
const written=entry(6,'Writing input','感谢欢迎并说明负责App设计','写下你的回复…');action(6,'Meaning disclosure',()=>sheet('Alex 在问什么？','「欢迎加入团队！你会负责什么工作？」可以先感谢欢迎，再说明自己负责的工作。'));action(6,'Writing hint',()=>sheet('一个自然的开头','Thanks for the warm welcome. 接着说明你会负责 App 的设计。'));action(6,'提交回复',()=>{if(!written.value.trim()){written.focus();note(6,'先写下你的回复。');return}sheet('回复参考','Thanks for the warm welcome! I’ll be working on the app design. 这句先感谢，再交代工作内容。正式版会针对你的原句分别评估意思、语法和语气；本原型展示参考表达。','继续，无提示检验',()=>show(7))});
const checked=entry(7,'Check input','用英文说她刚加入销售团队','你的英文表达…');action(7,'Check voice option',()=>sheet('本原型使用文字检验','语音评估尚未接入；请在输入区写出你会说的句子。','开始作答',()=>checked.focus()));action(7,'提交检验',()=>{if(!checked.value.trim()){checked.focus();note(7,'请先独立完成这句话。');return}const ok=['she just joined the sales team','she has just joined the sales team'].includes(clean(checked.value));sheet(ok?'这次迁移成功了':'记录下来，明天再练',ok?'你把 joined 用到了新的团队与人物。本题通过；接下来的汇总页其他成绩仍为示例数据。':'一种可用表达是：She just joined the sales team. 本原型只核对固定示例，其他有效说法留给正式评估。','查看今日完成',()=>show(8))});
action(8,'看看这周的变化',()=>show(9));action(9,'Plus entry',()=>show(11));action(9,'Recording comparison',()=>sheet('对比自己的表达','正式版会保存经你同意的练习录音，供前后对比。本原型没有真实学习录音，也没有编造音频成绩。'));action(9,'本月',()=>sheet('月度成长','正式版将展示一个月的同难度任务和间隔保持变化。本次仅演示本周示例数据。'));action(9,'本周',()=>note(9,'正在查看本周示例。'));
for(const filter of ['全部','待巩固','会独立用'])action(10,filter,()=>{const list=find(10,'Sentence list');const groups=[...list.children].filter(el=>el.dataset.pencilName!=='Separator');groups.forEach((el,i)=>el.style.display=filter==='全部'||filter==='待巩固'&&i===0||filter==='会独立用'&&i===1?'flex':'none');[...list.children].filter(el=>el.dataset.pencilName==='Separator').forEach(el=>el.style.display=filter==='全部'?'block':'none')});
for(const text of ['I just joined the team.','I usually start work at nine.','Thanks for the warm welcome.']){const item=find(10,text);const icon=[...item.querySelectorAll('[data-pencil-name]')].find(el=>el.dataset.pencilName==='speaker.wave.2');if(icon){icon.classList.add('action','icon-action');icon.tabIndex=0;icon.setAttribute('role','button');icon.setAttribute('aria-label','朗读 '+text);icon.onclick=()=>speak(text);icon.onkeydown=e=>{if(e.key==='Enter')speak(text)}}}
action(11,'查看方案说明',()=>sheet('Plus 方案假设','¥29 / 月仅用于验证付费意愿。拟提供个性化情境、口语与写作纠错、练习记录与进步对比。正式收费前需要验证反馈质量、服务成本、隐私选项与取消订阅方式。此原型不会购买或扣费。'));
